document.addEventListener(
  'DOMContentLoaded',
  function () {
    setTimeout(() => {
      const setImages = true // ÔćÉ toggle this true/false as needed


      // If true, only use specific video indexes for carousel
      const selectedIndexesUser = [1, 2, 3, 4] 
